    "t": "基底核を含む系を錐体外路系といい、皮質脊髄路（錐体路）とは区別する。ただしUTHealthは、基底核が独立した運動の経路をつくるのではなく、運動皮質や下行路の活動を調節すると説明する。運動障害疾患の原因となる病変の大部分は錐体外路系に生じる。運動が減る障害（運動減少症。パーキンソン病が代表）と、運動が過剰になる障害（振戦・舞踏運動・アテトーゼ・ヘミバリスム・ジストニアなど）に分けられる。",
