    "t": "直接路: 大脳皮質→（興奮）線条体→（抑制）淡蒼球内節・黒質網様部→（抑制）視床→（興奮）大脳皮質。抑制が二重にかかる（線条体が内節を抑え、内節による視床の抑制がはずれる＝脱抑制）ため、視床が皮質を興奮させ、運動が促される。",
