    "t": "間接路: 大脳皮質→（興奮）線条体→（抑制）淡蒼球外節→（抑制）視床下核→（興奮）淡蒼球内節・黒質網様部→（抑制）視床。外節による視床下核の抑制がはずれて視床下核が活動し、内節による視床の抑制が強まるため、運動が抑えられる。視床下核から淡蒼球内節・黒質網様部への投射は、基底核の内部の連絡のなかで唯一の興奮性の連絡。",
