    "t": "浮腫は、組織液が過剰にたまった状態。血漿タンパクが毛細血管内に水を引き戻す力（膠質浸透圧）をつくるため、タンパクが減ると再吸収が弱まる。出典は、血漿タンパクの多くが肝臓でつくられること、重度のタンパク欠乏が浮腫の原因になることを述べる。国試では「肝障害では浮腫は生じない」が誤り（50-am-64）、下肢の浮腫と低栄養がある患者で参考にする血液検査の正答は血清アルブミン（49-pm-18）だった。",
