  "figures": [
   {
    "src": "/organs/brachial-plexus.svg",
    "alt": "腕神経叢の模式図。左から、根（C5・C6・C7・C8・T1）、幹（上・中・下神経幹）、分枝（各幹の前部と後部）、束（外側・内側・後神経束）、終枝（筋皮神経・正中神経・尺骨神経・橈骨神経・腋窩神経）の順に並ぶ。C5・C6が上神経幹、C7が中神経幹、C8・T1が下神経幹をつくる。上・中神経幹の前部が外側神経束、下神経幹の前部が内側神経束、上・中・下神経幹の後部が後神経束になる。外側神経束から筋皮神経と正中神経の外側根、内側神経束から尺骨神経と正中神経の内側根、後神経束から橈骨神経と腋窩神経が出る。C5〜C7は新生児の上位（Erb麻痺）、C8・T1は新生児の下位（Klumpke麻痺）にあたる根として色を分けて示す（MSDマニュアルの区分）。",
    "caption": "腕神経叢の模式図（根→幹→分枝→束→終枝）。つながりを示すもので、実際の位置・太さ・長さは異なります。主な終枝のみを描き、鎖骨上部の枝（長胸神経など）や胸筋神経・肩甲下神経・胸背神経は省いています。根の色分けは、MSDマニュアル（新生児の腕神経叢損傷）の上位・下位の区分（C5〜C7／C8〜T1）です。成人の上位型・下位型（日本整形外科学会）の根の範囲とは、必ずしも一致しません。"
   }
  ],
