    "t": "脳神経の運動核は3群に分けられる。眼を動かす筋と舌の筋を支配する核（動眼・滑車・外転・舌下神経核）、鰓弓由来の筋（咀嚼筋・表情筋・咽頭と喉頭の筋）を支配する核（三叉神経運動核・顔面神経核・疑核）、平滑筋・心筋・腺を支配する自律性の核（動眼神経副核・上唾液核・迷走神経背側運動核・下唾液核）。感覚の核には、三叉神経の3つの核（脊髄路核・主知覚核・中脳路核）、孤束核、前庭神経核、蝸牛神経核などがある。",
