  "figures": [
   {
    "src": "/organs/brainstem.svg",
    "alt": "脳幹を前から見た模式図。上から中脳（左右の大脳脚と、そのあいだの脚間窩）、橋（横縞のある膨らみと、横に出る中小脳脚）、延髄（錐体、オリーブ、下端の錐体交叉）が並び、脊髄へ続く。脳神経が出る位置を赤い丸で示す。動眼神経は脚間窩、三叉神経は橋の外側、外転神経は橋と延髄の境の正中付近、顔面神経と内耳神経は橋と延髄の境の外側、舌咽神経・迷走神経・副神経はオリーブの背側、舌下神経はオリーブと錐体の間から出る。",
    "caption": "脳幹を前面から見た模式図（中脳・橋・延髄と、出る脳神経）。位置関係を示すもので、大きさ・形は実物と異なります。滑車神経（Ⅳ）は背側から出るため描いていません。顔面神経（Ⅶ）と内耳神経（Ⅷ）は、どちらも橋と延髄の境の外側（内耳神経は橋の尾端の外側）から出ると出典に書かれていますが、両者の左右・上下の並びについて細かい記述はなく、図の並びは概略です。"
   },
   {
    "src": "/organs/brainstem-4.svg",
    "alt": "脳幹の高さ別の脳神経核の一覧。中脳：動眼神経核、滑車神経核、動眼神経副核（自律性）、三叉神経中脳路核。橋：外転神経核、三叉神経運動核、顔面神経核、三叉神経主知覚核、前庭神経核、蝸牛神経核。延髄：舌下神経核、疑核、迷走神経背側運動核（自律性）、孤束核、三叉神経脊髄路核。",
    "caption": "脳幹の高さ別の脳神経核の一覧。核の性質（眼・舌を動かす／咀嚼・表情・咽頭喉頭を動かす／自律性／感覚）で色分けしています。三叉神経中脳路核は橋の高さから中脳まで、三叉神経脊髄路核は延髄から第2頸髄まで伸びます。上唾液核・下唾液核は、明瞭な細胞集団を作らず網様体の中に散らばるため描いていません。前庭神経核・蝸牛神経核は、北大の資料に従い橋に置いていますが、前庭神経核は標準神経病学が延髄の構造に挙げており、出典により高さの扱いが異なります。"
   },
   {
    "src": "/organs/brainstem-2.svg",
    "alt": "脳幹の断面の模式図（中脳と橋）。上は中脳の上丘の高さ。背側に上丘（中脳蓋）、中脳水道を囲む中心灰白質、その腹側に動眼神経核。被蓋に赤核があり、外方に内側毛帯が位置する。動眼神経根は赤核を貫いて脚間窩へ向かう。腹側に大脳脚があり、そのすぐ背側に黒質がある。下は橋の尾側。第四脳室の底の正中寄りに外転神経核（顔面神経丘の下）と内側縦束、外側に前庭神経核、さらに外側に三叉神経脊髄路核、その腹内側に顔面神経核がある。橋網様体は被蓋の中央にあり、被蓋の腹側縁に内側毛帯が広がる。それより腹側の橋腹側部（橋底部）には、橋核・縦橋線維・横橋線維があり、横橋線維は中小脳脚へ続く。",
    "caption": "脳幹の断面の模式図（上：中脳の上丘の高さ、下：橋の尾側）。位置関係を示すもので、大きさ・形は実物と異なります。背側を上、腹側を下に描いています。核や伝導路の左右対称な配置を示した概略図で、細かい形や広がりは実物と異なります。出典に位置の記述がある並び（動眼神経核は中心灰白質の腹側、赤核の外方に内側毛帯、黒質は大脳脚のすぐ背側、外転神経核は顔面神経丘の下、顔面神経核は三叉神経脊髄路核の腹内側、内側毛帯が橋背部と橋腹側部の境、など）をもとにしていますが、前庭神経核と三叉神経脊髄路核の外側への並び、橋網様体・内側縦束・橋核の細かい位置は出典に細かい記述がなく概略です。縦橋線維には錐体路（皮質脊髄路・皮質核路）と皮質橋路が含まれます。"
   },
   {
    "src": "/organs/brainstem-3.svg",
    "alt": "延髄の断面の模式図（下部と上部）。上は延髄下部（中心管がある高さ）。背側に薄束核（内側）と楔状束核（外側）、その外側に三叉神経脊髄路核。後索核から出た内弓状線維が腹側へ回って正中で交叉（毛帯交叉）し、内側毛帯となって上行する。腹側に左右の錐体がある。下は延髄上部（オリーブの高さ、第四脳室が開く）。第四脳室の底の正中寄りに舌下神経核、その外側に迷走神経背側核。外側の背側に三叉神経脊髄路核、外側縁に後脊髄小脳路と、その腹側に外側脊髄視床路。三叉神経脊髄路核とオリーブ核の中間に疑核。腹外側にオリーブ核、正中寄りに内側毛帯、腹側に錐体。舌下神経の根は内側毛帯の外側を下り、錐体とオリーブの間から出る。",
    "caption": "延髄の断面の模式図（上：下部、毛帯交叉の高さ、下：上部、オリーブの高さ）。位置関係を示すもので、大きさ・形は実物と異なります。背側を上、腹側を下に描いています。出典の記述で確かめられた並びだけで示した概略図で、細かい形や広がりは実物と異なります。内側毛帯のこまかな位置は概略です。"
   }
  ],
