    "src": "/organs/fetal-circulation.svg",
    "alt": "胎児の血液循環の模式図。胎盤から臍静脈が酸素の多い血液を運び、一部は肝臓を通り、一部は静脈管を通って下大静脈に入る。下大静脈の血液は右心房から卵円孔を通って左心房に流れ、左心室から大動脈に出て上半身へ向かう。上大静脈の血液は右心房から右心室、肺動脈幹に入り、大部分は動脈管を通って大動脈に流れ、肺にはわずかしか流れない。下半身の血液は臍動脈で胎盤へ戻る。赤は酸素が多い血液、青は酸素が少ない血液、紫はその中間。",
