    "t": "出典の記述: 低換気による低酸素血症では(A-a)DO₂は正常で、換気血流比の低下・右左短絡・拡散障害では開く。国試の正答は、Ⅱ型呼吸不全では正常でⅠ型呼吸不全で増加するのは肺胞気-動脈血酸素分圧較差。",
