    "alt": "外呼吸と内呼吸のガスの動きの模式図。外呼吸では、酸素が肺胞気（PO2約104）から肺毛細血管の血液（流入時約40）へ、二酸化炭素が血液（PCO2約45）から肺胞気（約40）へ移る。内呼吸では、酸素が血液から組織（PO2約40）へ、二酸化炭素が組織から血液へ移る。",
