   {
    "src": "/organs/heart.svg",
    "alt": "心臓を前から見た模式図。上に右心房と左心房、下に右心室と左心室がある。右心房と右心室の間に三尖弁、右心室の出口に肺動脈弁、左心房と左心室の間に僧帽弁、左心室の出口に大動脈弁がある。上大静脈と下大静脈が右心房に入り、右心室から肺動脈幹が出る。肺静脈が左心房に入り、左心室から大動脈が出る。青い矢印は酸素の少ない血液、赤い矢印は酸素の多い血液の向きを示す。",
    "caption": "心臓を前から見た模式図（図の左が体の右側）。位置関係を示すもので、大きさ・形は実物と異なります。弁は小さな四角で示し、弁尖の数や開閉は表していません。肺静脈は実際は4本ありますが、図では2本に簡略化しています。大動脈弓の枝や下行大動脈は省き、肺動脈幹・大動脈の太さや曲がりも簡略化しています。"
   },
   {
    "src": "/organs/heart-2.svg",
    "alt": "心臓の刺激伝導系の模式図。右心房の上大静脈の近くにある洞房結節から興奮が始まり、心房に広がって房室結節に届く。房室結節から房室束（ヒス束）が心室中隔に入り、右脚と左脚に分かれて心尖に向かい、プルキンエ線維が心室の壁に広がる。",
    "caption": "刺激伝導系の模式図。興奮が伝わる順に①から⑤の番号をつけています。位置関係を示すもので、大きさ・形は実物と異なります。房室結節への経路（結節間路）、左脚の枝分かれ、プルキンエ線維の広がりは簡略化しています。"
   }
