    "alt": "肝臓を前から見た模式図。右上腹部で横隔膜の下にあり、体の右側（図の左）に大きな右葉、左側に小さな左葉がある。右葉と左葉の間を鎌状間膜が分け、その下縁に肝円索が付く。胆嚢は右葉の下縁の近くに見える。",
    "caption": "肝臓の位置と葉の模式図（前から見た図）。位置関係を示すもので、大きさ・形は実物と異なります。方形葉・尾状葉・肝門は、この図では見えません。胆嚢は右葉の後面のくぼみにあり（出典）、図では下縁の近くに見える位置は目安です。肝円索と鎌状間膜の位置関係も目安です。"
