    "src": "/organs/liver-2.svg",
    "alt": "肝小葉の血流の模式図。六角形の小葉の周辺に、門脈の枝・肝動脈の枝・胆管からなる門脈三管がある。門脈の枝と肝動脈の枝の血液は類洞で混ざり、小葉の中心の中心静脈に流れ込み、肝静脈から下大静脈へ向かう。胆汁は、肝細胞の間の毛細胆管を通り、血液とは逆向きに周辺の胆管へ流れる。",
    "caption": "肝小葉の血液と胆汁の流れの模式図。実際の小葉は多数が並び、形は実物と異なります。"
