    "alt": "腰仙骨神経叢の模式図。左に腰神経叢（腰神経から）の枝として、大腿神経（縫工筋・恥骨筋・大腿四頭筋、枝は伏在神経）と閉鎖神経（内転筋群・外閉鎖筋）、ほかに外側大腿皮神経・陰部大腿神経・腸骨下腹神経・腸骨鼠径神経・腰仙骨神経幹。右に仙骨神経叢（L4・L5・S1〜S4）の枝として、梨状筋上孔を通る上殿神経（中殿筋・小殿筋・大腿筋膜張筋）、梨状筋下孔を通る下殿神経（大殿筋）・坐骨神経（脛骨神経と総腓骨神経に分かれ、総腓骨神経は浅腓骨神経と深腓骨神経に分かれる）・陰部神経（第2〜第4仙骨神経、小坐骨孔から骨盤内に再び入る）・後大腿皮神経。",
    "caption": "腰仙骨神経叢の枝の名前と、通る孔・主な支配筋の対応を示した模式図。神経の位置・太さ・長さは実物と異なります。神経叢を構成する神経根ごとの対応（髄節）は、使った出典で確かめられた範囲（腰神経叢：腰神経／仙骨神経叢：L4・L5・S1〜S4、上殿神経：L4・L5・S1、陰部神経：S2〜S4）のみ示しています。下殿神経を仙骨神経叢の側に置いているのは、梨状筋下孔を通る点（北大）と一般的な分類によるもので、「仙骨神経叢の枝」と直接書いた出典は確かめられていません。上殿神経の神経根（L4・L5・S1）は、荒川（2015）の抄録の記述です。"
