   "t": "肺気量分画は、肺の中の空気の量を、4つの1次分画（予備吸気量・1回換気量・予備呼気量・残気量）と、それらを2つ以上合わせた4つの2次分画（全肺気量・肺活量・最大吸気量・機能的残気量）で表したもの。スパイログラムで記録する。",
