    "t": "SO線維は、姿勢の保持、等尺性収縮、骨や関節の安定、頻繁だが小さな動きに使われる。FOG線維は、歩行のような、姿勢の保持より多くのエネルギーを要するが、全力疾走ほどではない動きに使われる。FG線維は、短時間の素早く強い動きに使われる。",
