    "t": "筋が急に引き伸ばされると（腱をハンマーで叩く、など）、筋紡錘が興奮し、Ia線維が脊髄に入って、同じ筋のα運動ニューロンに興奮性シナプスをつくる。シナプスが1つだけなので単シナプス反射で、その筋が収縮する（伸張反射）。協働筋も興奮することがある。",
