  "structure": [
   {
    "t": "細胞体（ソーマ）は核と主な細胞小器官をもつ。細胞体からは突起が出る。軸索は通常1本で、ほかの突起が樹状突起。",
    "s": [
     1,
     3
    ]
   },
   {
    "t": "樹状突起は、ほかのニューロンからの入力をシナプスで受け取る。情報は、樹状突起→細胞体→軸索の向きに流れる（極性）。",
    "s": [
     1
    ]
   },
   {
    "t": "軸索は、軸索小丘（細胞体が軸索へ移る部分）、軸索起始部、軸索（固有部）、軸索終末に分けられる。活動電位は、軸索小丘と起始部（トリガーゾーン）でつくられる。",
    "s": [
     1,
     3
    ]
   },
   {
    "t": "軸索終末は枝分かれして、先端がふくらんだシナプス終末（シナプス端球）になり、標的の細胞とシナプスをつくる。",
    "s": [
     1
    ]
   },
   {
    "t": "突起の数による分類。偽単極ニューロンは感覚ニューロンで、細胞体は必ず神経節にある。双極ニューロンは嗅上皮と網膜にみられる。それ以外のほとんどは多極ニューロン（1本の軸索と2本以上の樹状突起）。",
    "s": [
     1
    ]
   },
   {
    "t": "髄鞘（ミエリン）は、軸索を何重にも包む、脂質に富む絶縁性の膜で、グリア細胞がつくる。髄鞘をもつ軸索を有髄線維、もたないものを無髄線維という。",
    "s": [
     4,
     3,
     1
    ]
   },
   {
    "t": "髄鞘をつくる細胞は、中枢神経系では希突起膠細胞（オリゴデンドロサイト）、末梢神経系ではシュワン細胞。希突起膠細胞は、1つの細胞から出る複数の突起で、複数の軸索の節を包む。シュワン細胞は、1つの軸索の1つの節だけを包む。",
    "s": [
     1,
     3,
     4
    ]
   },
   {
    "t": "髄鞘は一定の間隔で途切れ、その隙間をランビエ絞輪という（1〜2 mmおき、隙間は1 µm程度）。絞輪には電位依存性のチャネルが集まっている。",
    "s": [
     5
    ]
   },
   {
    "t": "グリア細胞は神経細胞を支える細胞。中枢神経系には、星状膠細胞（アストロサイト）・希突起膠細胞・小膠細胞（ミクログリア）・上衣細胞、末梢神経系には、衛星細胞とシュワン細胞がある。",
    "s": [
     1
    ]
   }
  ],
  "function": [
   {
    "t": "ニューロンは、電気信号（活動電位）で情報を伝え、シナプスで化学信号（神経伝達物質）に換えて、次の細胞に伝える。",
    "s": [
     1
    ]
   },
   {
    "t": "星状膠細胞は、細胞外の化学物質の濃度の維持や血液脳関門に関わる。小膠細胞は、中枢神経系にいる免疫の監視と貪食の細胞。上衣細胞は、脳室で脳脊髄液をつくる。衛星細胞は、神経節で神経細胞体を囲んで支える。",
    "s": [
     1
    ]
   }
  ],
  "mechanism": [
   {
    "t": "有髄線維では、髄鞘に包まれた部分には電位依存性Naチャネルがなく、絞輪に集まっている。Na+が軸索の内側を広がって、次の絞輪で閾値を超える脱分極を起こすので、活動電位は絞輪から絞輪へ飛び飛びに生じて伝わる（跳躍伝導）。無髄線維では、軸索の全長に沿って連続的に伝わる（連続伝導）。",
    "s": [
     2,
     4,
     5
    ]
   },
   {
    "t": "跳躍伝導は連続伝導より速い。絞輪の間隔は、次の絞輪で閾値を超えた脱分極が保たれるのにちょうどよい距離で、もっと離れると脱分極が弱まりすぎ、もっと近いと速度が落ちる。跳躍伝導の速さの目安は30〜160 m/sで、信号は減衰しない。",
    "s": [
     2,
     5
    ]
   },
   {
    "t": "髄鞘が傷つく（脱髄）と、神経伝導速度が遅くなる。脱髄は主に太い有髄線維に起こる。中枢神経系の脱髄疾患が多発性硬化症、末梢神経系の脱髄疾患がギラン・バレー症候群。",
    "s": [
     6,
     1
    ]
   },
   {
    "t": "神経伝導検査では、太い有髄線維が傷つくと伝導速度の低下が前に出る。細い線維や無髄線維だけが傷つくと、活動電位の振幅が減り、伝導速度はほぼ正常のまま。",
    "s": [
     7
    ]
   }
  ],
  "examPoints": [
   {
    "t": "中枢神経系で髄鞘をつくるのは希突起膠細胞（オリゴデンドロサイト）。末梢神経系ではシュワン細胞。星状膠細胞は支持と血液脳関門、小膠細胞は免疫の監視と貪食、上衣細胞は脳脊髄液をつくる。54-pm-54は、中枢神経系の模式図で希突起膠細胞を選ぶ問題（図は確認していない）。",
    "q": [
     "54-pm-54"
    ],
    "s": [
     1,
     4
    ]
   },
   {
    "t": "体性感覚の一次ニューロン（偽単極ニューロン）の細胞体は、脊髄後根神経節にある。脊髄後角・延髄・視床・大脳皮質ではない。出典（OpenStax）は、偽単極ニューロンの細胞体は必ず神経節にあると書く。",
    "q": [
     "56-pm-56",
     "59-pm-55"
    ],
    "s": [
     1
    ]
   },
   {
    "t": "有髄線維で活動電位が生じるのは絞輪で、髄鞘ではない（52-pm-61で「興奮が髄鞘に伝わる」は誤り）。有髄線維は跳躍伝導で伝導速度が速い。",
    "q": [
     "52-pm-61"
    ],
    "s": [
     2,
     4
    ]
   },
   {
    "t": "脱髄病変では神経伝導速度が低下する（57-am-91の正答）。54-am-7は、正中神経の運動神経伝導検査の波形（図）から病態を選ぶ問題で、正答は脱髄。図は確認していない。",
    "q": [
     "57-am-91",
     "54-am-7"
    ],
    "s": [
     6,
     7
    ]
   }
  ],
