    "alt": "視床下部の下に漏斗でつながる下垂体を横から見た模式図。下垂体は蝶形骨のトルコ鞍におさまり、前葉（腺性）と後葉（神経性）からなる。視床下部の放出・抑制ホルモンは、第一次毛細血管叢から下垂体門脈を通って前葉の第二次毛細血管叢に届く。室傍核・視索上核の神経細胞の軸索は後葉に達し、バソプレシンとオキシトシンを血中に放出する。前葉のホルモンはGH・PRL・TSH・ACTH・FSH・LH。",
