    "alt": "視床下部の放出ホルモンが下垂体前葉を刺激し、下垂体前葉の刺激ホルモンが標的腺を刺激し、標的腺のホルモンが標的組織に作用する流れ図。標的腺のホルモンが増えると、視床下部と下垂体前葉に負のフィードバックがかかる。",
    "caption": "視床下部—下垂体—標的腺の階層と負のフィードバックの模式図。例として、TRH→TSH→T3・T4、CRH→ACTH→コルチゾール、GnRH→LH・FSH→性ホルモン。"
