    "t": "食べ物の大部分が吸収されて壁の伸展が少なくなると、分節運動に代わって、移動性運動複合体が出る。十二指腸の粘膜が出すホルモンのモチリンが引き起こし、内容物を少しずつ先へ送る。90〜120分かけて回腸の末端に達する。",
