    "t": "視床痛: 非侵害刺激でも痛みを感じる（アロディニア。55-am-87の正答）。灼熱感を生じる痛みは視床痛（57-pm-89）。脳卒中の発症直後ではなく、多くは数か月後に生じる（55-am-87の「発症直後から出現」は誤り）。出典（日本ペインクリニック学会）に「視床痛」の語はなく、脳卒中後疼痛（主に視床などの体性感覚系の障害後）の中の脳卒中後中枢痛（CPSP）が、灼けるような痛み・痛覚過敏・アロディニアを伴う痛みとして書かれている。国試の「視床痛」はこの痛みにあたるとして扱うが、用語の対応は出典で確認していない。出典は、CRPSを脳卒中後疼痛の中でCPSPとは別に挙げる。CRPS type Ⅰに分類されるのは肩手症候群とSudeck骨萎縮が正答で、視床痛は誤りの選択肢（58-pm-89、55-am-87）。",
