    "alt": "視床の主な核を中央に、入力元を左に、大脳皮質の投射先を右に並べた図。前核は乳頭体から帯状回へ。内側核は扁桃体・側頭葉・視床下部から前頭葉へ。前外側腹側核（VA・VL）は小脳歯状核・淡蒼球・黒質から運動前野・運動野へ。後外側腹側核（VPL）は脊髄視床路・内側毛帯から、後内側腹側核（VPM）は三叉神経毛帯から、どちらも中心後回へ。外側膝状体は視索から後頭葉へ、内側膝状体は下丘から側頭葉の横側頭回へ。",
