    "t": "尿管は、腎盂から続き、後腹膜を大腰筋の上で下り、総腸骨動脈の分かれ目の前を越える。骨盤の側壁に沿って下り、内側へ向きを変えて、膀胱の後ろ側に入る。上半分は腹部、下半分は骨盤内にある。",
