    "alt": "糸球体濾過の模式図。輸入細動脈から糸球体毛細血管に入った血漿が、有窓内皮・基底膜・足細胞の濾過スリットからなる濾過膜を通ってボウマン嚢へ濾過される。濾過を押し出す糸球体血圧55 mmHgに、ボウマン嚢内圧15 mmHgと血漿膠質浸透圧30 mmHgが逆らい、正味約10 mmHgで濾過される。血球とアルブミンは濾過膜を通らず輸出細動脈へ残る。",
    "caption": "糸球体濾過の模式図と有効濾過圧。数値はOpenStaxの平均的な値です。"
